// Package agentdocs serves the documentation this repo generates for agents.
//
// Routes, all unauthenticated on purpose — an agent needs to learn the API before
// it has a key, and every one of these files is public on GitHub anyway:
//
//	GET /llms.txt          the llmstxt.org v2 index: H1, summary, then H2 file lists
//	GET /llms-full.txt     every document concatenated, for a large context window
//	GET /docs              the manifest as JSON: version, API version, per-doc sha256
//	GET /docs/<slug>.md    one document as markdown
//
// The content is generated by cmd/docsgen from the tracked markdown in this repo,
// not written here. That is the whole point: there is one copy of the truth, and
// `docsgen -check` fails CI when the served copy falls behind it.
package agentdocs

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"path"
	"strings"

	"github.com/gin-gonic/gin"
)

//go:embed content/*.md docs.json llms.txt llms-full.txt
var files embed.FS

// Doc is one served document, as described by docs.json.
type Doc struct {
	Slug    string `json:"slug"`
	Title   string `json:"title"`
	Summary string `json:"summary"`
	Section string `json:"section"`
	URL     string `json:"url"`
	Source  string `json:"source"`
	Bytes   int    `json:"bytes"`
	SHA256  string `json:"sha256"`
}

// Manifest is the machine-readable description of the served set. Compare
// Version against what you cached to know whether anything changed; it is a
// digest of every document's content, so the same version means the same bytes.
type Manifest struct {
	Version    string `json:"version"`
	APIVersion string `json:"api_version"`
	DocCount   int    `json:"doc_count"`
	Docs       []Doc  `json:"docs"`
}

// Bundle is the parsed, ready-to-serve documentation set.
type Bundle struct {
	manifest Manifest
	index    []byte
	full     []byte
	docs     map[string][]byte // slug -> markdown
	etag     string
}

// Load parses the embedded files. Call it once at startup; the returned Bundle is
// read-only and safe to share.
func Load() (*Bundle, error) {
	raw, err := files.ReadFile("docs.json")
	if err != nil {
		return nil, fmt.Errorf("agentdocs: manifest: %w", err)
	}
	var m Manifest
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, fmt.Errorf("agentdocs: manifest: %w", err)
	}
	if len(m.Docs) == 0 {
		return nil, fmt.Errorf("agentdocs: manifest lists no documents (run: go run ./cmd/docsgen)")
	}

	index, err := files.ReadFile("llms.txt")
	if err != nil {
		return nil, fmt.Errorf("agentdocs: llms.txt: %w", err)
	}
	full, err := files.ReadFile("llms-full.txt")
	if err != nil {
		return nil, fmt.Errorf("agentdocs: llms-full.txt: %w", err)
	}

	docs := make(map[string][]byte, len(m.Docs))
	for _, d := range m.Docs {
		body, err := files.ReadFile(path.Join("content", d.Slug+".md"))
		if err != nil {
			return nil, fmt.Errorf("agentdocs: content/%s.md (listed in the manifest): %w", d.Slug, err)
		}
		// The manifest's hash is the contract that the served bytes are the ones
		// the version describes. Checking it at startup turns "someone edited the
		// generated file by hand" into a boot failure instead of a quiet lie.
		sum := sha256.Sum256(body)
		if got := hex.EncodeToString(sum[:]); got != d.SHA256 {
			return nil, fmt.Errorf("agentdocs: content/%s.md does not match the manifest (want %s, got %s); run: go run ./cmd/docsgen",
				d.Slug, d.SHA256, got)
		}
		docs[d.Slug] = body
	}

	return &Bundle{
		manifest: m,
		index:    index,
		full:     full,
		docs:     docs,
		etag:     `"docs-` + m.Version + `"`,
	}, nil
}

// Manifest returns the parsed manifest.
func (b *Bundle) Manifest() Manifest { return b.manifest }

// Routes mounts the documentation routes on r. They are unauthenticated: see the
// package comment.
func (b *Bundle) Routes(r gin.IRouter) {
	r.GET("/llms.txt", b.serveText(b.index, "text/plain; charset=utf-8"))
	r.GET("/llms-full.txt", b.serveText(b.full, "text/plain; charset=utf-8"))
	r.GET("/docs", b.serveManifest)
	r.GET("/docs/:file", b.serveDoc)
}

// serveText writes a whole file with the version headers and a cheap revalidation
// path: an agent that already has the docs sends If-None-Match and gets a 304.
func (b *Bundle) serveText(body []byte, contentType string) gin.HandlerFunc {
	return func(c *gin.Context) {
		b.headers(c, contentType)
		if c.GetHeader("If-None-Match") == b.etag {
			c.Status(http.StatusNotModified)
			return
		}
		c.Data(http.StatusOK, contentType, body)
	}
}

func (b *Bundle) serveManifest(c *gin.Context) {
	b.headers(c, "application/json; charset=utf-8")
	if c.GetHeader("If-None-Match") == b.etag {
		c.Status(http.StatusNotModified)
		return
	}
	c.JSON(http.StatusOK, b.manifest)
}

func (b *Bundle) serveDoc(c *gin.Context) {
	name := c.Param("file")
	slug := strings.TrimSuffix(name, ".md")
	body, ok := b.docs[slug]
	if !ok {
		c.JSON(http.StatusNotFound, gin.H{
			"error":  fmt.Sprintf("no document %q", name),
			"docs":   "/docs",
			"llms":   "/llms.txt",
			"detail": "request /docs for the list of available slugs",
		})
		return
	}
	b.headers(c, "text/markdown; charset=utf-8")
	if c.GetHeader("If-None-Match") == b.etag {
		c.Status(http.StatusNotModified)
		return
	}
	c.Data(http.StatusOK, "text/markdown; charset=utf-8", body)
}

// headers stamps every response with what this set is. An agent that cached the
// docs can compare X-Docs-Version — or just rely on the ETag.
func (b *Bundle) headers(c *gin.Context, contentType string) {
	c.Header("X-Docs-Version", b.manifest.Version)
	c.Header("X-API-Version", b.manifest.APIVersion)
	c.Header("X-Docs-Count", fmt.Sprint(b.manifest.DocCount))
	c.Header("ETag", b.etag)
	// Revalidate rather than trust: the docs change with the code, and a stale
	// cached copy is exactly the failure this package exists to prevent.
	c.Header("Cache-Control", "public, max-age=0, must-revalidate")
	c.Header("Content-Type", contentType)
}
